import{_ as t,o,c as a,a7 as r}from"./chunks/framework.C4ZIv4ii.js";const u=JSON.parse('{"title":"Form Builder","description":"","frontmatter":{},"headers":[],"relativePath":"guide/forms.md","filePath":"guide/forms.md","lastUpdated":1788427780000}'),s={name:"guide/forms.md"};function i(d,e,n,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="form-builder" tabindex="-1">Form Builder <a class="header-anchor" href="#form-builder" aria-label="Permalink to &quot;Form Builder&quot;">​</a></h1><p>Build contact and lead-capture forms visually, drop them into any page with a shortcode, and read what people send you from the dashboard. Forms are part of the free core — no Pro license is needed.</p><h2 id="building-a-form" tabindex="-1">Building a form <a class="header-anchor" href="#building-a-form" aria-label="Permalink to &quot;Building a form&quot;">​</a></h2><p>Go to <strong>Forms</strong> in the dashboard and create one. The builder lets you add fields, set each one&#39;s label, placeholder and validation, and arrange them in the order visitors will see.</p><p>Eleven field types are available:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>text</code></td><td>single-line text</td></tr><tr><td><code>textarea</code></td><td>multi-line text</td></tr><tr><td><code>email</code></td><td>email address</td></tr><tr><td><code>tel</code></td><td>telephone number</td></tr><tr><td><code>number</code></td><td>numeric input</td></tr><tr><td><code>date</code></td><td>date picker</td></tr><tr><td><code>select</code></td><td>dropdown</td></tr><tr><td><code>radio</code></td><td>one choice from several</td></tr><tr><td><code>checkbox</code></td><td>one or more choices</td></tr><tr><td><code>file</code></td><td>file upload</td></tr><tr><td><code>hidden</code></td><td>a value the visitor does not see</td></tr></tbody></table><h2 id="putting-a-form-on-a-page" tabindex="-1">Putting a form on a page <a class="header-anchor" href="#putting-a-form-on-a-page" aria-label="Permalink to &quot;Putting a form on a page&quot;">​</a></h2><p>Every form has a slug, and the builder shows you the shortcode to copy:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[falcon_form slug=&quot;contact&quot;]</span></span></code></pre></div><p>Paste it into any page, post, or a Text element in the page builder. It renders the form with your theme&#39;s styling.</p><h2 id="what-happens-on-submit" tabindex="-1">What happens on submit <a class="header-anchor" href="#what-happens-on-submit" aria-label="Permalink to &quot;What happens on submit&quot;">​</a></h2><p>You choose what the visitor sees after sending — either a <strong>success message</strong> shown in place, or a <strong>redirect</strong> to a URL of your choice.</p><p>Set a <strong>notification email</strong> on the form and each submission is emailed there as it arrives.</p><p>Every submission is also stored, so nothing depends on that email being delivered.</p><h2 id="reading-submissions" tabindex="-1">Reading submissions <a class="header-anchor" href="#reading-submissions" aria-label="Permalink to &quot;Reading submissions&quot;">​</a></h2><p><strong>Forms → Submissions</strong> lists everything that has come in, either per form or across all of them. Each row records:</p><ul><li>the submitted field values</li><li>the sender&#39;s IP address and user agent</li><li>whether it has been read yet</li></ul><p>Uploaded files are stored on the public disk and linked from the submission.</p><h2 id="spam-protection" tabindex="-1">Spam protection <a class="header-anchor" href="#spam-protection" aria-label="Permalink to &quot;Spam protection&quot;">​</a></h2><p>Two layers are applied automatically:</p><ul><li>a <strong>honeypot</strong> field, invisible to people but usually filled in by bots</li><li><strong>Cloudflare Turnstile</strong>, when you have configured it in the CMS settings</li></ul><p>Both are stripped from the stored data — you only ever see the fields you asked for.</p><h2 id="moving-a-form-between-sites" tabindex="-1">Moving a form between sites <a class="header-anchor" href="#moving-a-form-between-sites" aria-label="Permalink to &quot;Moving a form between sites&quot;">​</a></h2><p><strong>Export</strong> downloads the whole form as JSON — fields, labels, validation, success message and settings. <strong>Import</strong> recreates it on another site. Useful for reusing a contact form across projects, or for moving one from staging to live.</p><p>Submissions are not included in the export; only the form itself travels.</p>',25)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
